# New hypothesis: Group columns into "shapes" based on continuous non-zero blocks, then shift each shape independently
# To determine shift, find which shape's TOP matches some anchor position

def group_columns_to_shapes(grid):
    """Group consecutive columns with non-zero values into shape regions"""
    h, w = len(grid), len(grid[0])
    shape_regions = {}

    for c in range(w):
        # Find rows with non-zero values in this column
        rows = [r for r in range(h) if grid[r][c] != 0]
        if not rows:
            continue

        # Check if this column continues from previous column's shape
        prev_c = c - 1
        in_same_shape = False
        if prev_c >= 0:
            prev_rows = [r for r in range(h) if grid[r][prev_c] != 0]
            if prev_rows and max(prev_rows) > min(rows) - 1:
                in_same_shape = True

        if in_same_shape and c in shape_regions:
            shape_regions[c].append(c)
        else:
            shape_regions[c] = [c]

    return shape_regions

def compute_vertical_shift_per_column(grid):
    """Compute the vertical shift needed for each column based on its shape region"""
    h, w = len(grid), len(grid[0])

    # Get all colored cells sorted by column then row
    cols_with_colors = {}
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 0:
                if c not in cols_with_colors:
                    cols_with_colors[c] = []
                cols_with_colors[c].append((r, val))

    # For simplicity, use column average position as reference
    avg_rows_by_col = {}
    for c, cells in cols_with_colors.items():
        avg_rows_by_col[c] = sum(r for r, v in cells) / len(cells)

    # Compute shift relative to first colored column
    first_col = min(cols_with_colors.keys())
    first_avg = avg_rows_by_col[first_col]

    shifts = {}
    for c, avg_r in avg_rows_by_col.items():
        shifts[c] = int(round(avg_r - first_avg))

    return shifts, first_avg

